17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        owner.setCustomerCode(CustomerCode.of(owner, this.clinicService.findAllOwners()));
109	        this.clinicService.saveOwner(owner);
110	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
111	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        headers.setLocation(UriComponentsBuilder.newInstance()
114	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
115	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
121	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
122	        if (currentOwner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        currentOwner.setAddress(ownerFieldsDto.getAddress());
126	        currentOwner.setCity(ownerFieldsDto.getCity());
127	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
128	        currentOwner.setLastName(ownerFieldsDto.getLastName());
129	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
130	        this.clinicService.saveOwner(currentOwner);
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Transactional
136	    @Override
137	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        this.clinicService.deleteOwner(owner);
143	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Pet pet = petMapper.toPet(petFieldsDto);
155	        owner.setId(ownerId);
156	        pet.setOwner(owner);
157	        pet.getType().setName(null);
158	        this.clinicService.savePet(pet);
159	        PetDto petDto = petMapper.toPetDto(pet);
160	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
161	            .buildAndExpand(pet.getId()).toUri());
162	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner != null) {
170	            Pet currentPet = this.clinicService.findPetById(petId);
171	            if (currentPet != null) {
172	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
173	                currentPet.setName(petFieldsDto.getName());
